package ru.folio.notes;

import android.view.Choreographer;
import java.awt.*;
import java.awt.geom.*;
import java.awt.image.*;
import java.io.File;
import java.util.ArrayList;
import javax.imageio.ImageIO;

/** Exact motion formulas and the production frame clock; Android scheduling is replaced only in this JVM test. */
public final class PopoverMotionTests {
    static int assertions;
    static void check(boolean condition,String text){if(!condition)throw new AssertionError(text);assertions++;}
    static void curve(){
        check(PopoverMotion.expansion(0)==0&&PopoverMotion.expansion(1)==1,"exact opening endpoints");
        check(PopoverMotion.content(.08f)==0,"text waits for shell expansion");check(PopoverMotion.content(.4f)==1,"text fully visible after expansion");check(PopoverMotion.opacity(.14f)==1,"shell becomes visible early");
        float maximum=0;for(int frame=0;frame<=460;frame++){float t=frame/460f,k=PopoverMotion.expansion(t);check(Float.isFinite(k)&&k>=0&&k<1.08f,"bounded spring");check(PopoverMotion.opacity(t)>=0&&PopoverMotion.opacity(t)<=1,"bounded opacity");check(PopoverMotion.content(t)>=0&&PopoverMotion.content(t)<=1,"bounded text opacity");maximum=Math.max(maximum,k);}
        check(maximum>1.025f,"subtle expansion overshoot");check(Math.abs(PopoverMotion.expansion(.9f)-1)<.001,"settled tail");
        float sx=.14f,sy=.20f,dx=-12,dy=-87,w=302,h=282,x=390,y=154;
        float sourceX=x+dx+w*sx/2,sourceY=y+dy+h*sy/2;check(Math.abs(sourceX-399.14f)<.01,"source centre remains on selected tool");
        for(int frame=0;frame<=60;frame++){float t=frame/60f,k=PopoverMotion.expansion(t),scaleX=PopoverMotion.lerp(sx,1,k),scaleY=PopoverMotion.lerp(sy,1,k);check(scaleX>0&&scaleY>0,"positive card size");float corner=PopoverMotion.lerp(Math.min(w,h)/2,26,PopoverMotion.corner(t));check(corner>=26&&corner<=141,"round seed morphs to card");if(frame==0)check(Math.abs((x+dx*(1-k)+w*scaleX/2)-sourceX)<.001,"first frame starts on icon");}
        check(sourceY<y,"upper toolbar seed expands downward");System.out.println("PASS reference motion, delayed text, rounded seed, overshoot and anchor mapping");
    }
    static void clock(){
        Choreographer scheduler=Choreographer.getInstance();long start=1000000000L;FrameClock clock=new FrameClock(()->start);ArrayList<Float> samples=new ArrayList<>();int[] done={0};clock.start(460,samples::add,()->done[0]++);check(samples.size()==1&&samples.get(0)==0,"zero frame set before first draw");check(clock.running,"clock starts independent of platform animators");
        scheduler.advance(start);scheduler.advance(start+80000000);check(samples.get(samples.size()-1)>0&&samples.get(samples.size()-1)<1,"visible intermediate frame");
        // A layout update only reapplies a sample; it must not cancel or restart the clock.
        float before=samples.get(samples.size()-1);float measured=PopoverMotion.expansion(before);check(measured<1&&clock.running,"layout can redraw intermediate state");scheduler.advance(start+160000000);check(samples.get(samples.size()-1)>before,"progress continues after layout redraw");scheduler.advance(start+460000000);check(!clock.running&&done[0]==1,"finishes once");check(scheduler.pending()==0,"no frame loop after completion");
        clock.start(460,samples::add,()->done[0]++);clock.cancel();int count=samples.size();scheduler.advance(start+900000000);check(samples.size()==count&&done[0]==1&&scheduler.pending()==0,"detached card cancels callbacks");
        clock.start(460,t->{if(t>.1)clock.cancel();},()->done[0]++);scheduler.advance(start);scheduler.advance(start+100000000);check(!clock.running&&scheduler.pending()==0&&done[0]==1,"cancellation inside a frame never completes dismissal");
        clock.start(180,samples::add,()->done[0]++);scheduler.advance(start);scheduler.advance(start+180000000);check(done[0]==2,"closing completion fires once");
        final FrameClock restart=new FrameClock(()->start);int[] completions={0};restart.start(100,t->{if(t>=1)restart.start(100,u->{},()->completions[0]++);},()->completions[0]+=100);scheduler.advance(start+100000000);check(completions[0]==0&&scheduler.pending()==1,"reentrant restart does not complete or duplicate old animation");scheduler.advance(start+200000000);check(completions[0]==1&&scheduler.pending()==0,"restarted animation completes once");
        restart.start(100,t->{},null);scheduler.advance(start+8000000);check(restart.running,"first vsync advances immediately");restart.cancel();System.out.println("PASS frame clock startup, intermediate frames, completion, cancellation and reentrant restart");
    }
    static BufferedImage backdrop(){BufferedImage b=new BufferedImage(760,560,BufferedImage.TYPE_INT_RGB);Graphics2D g=b.createGraphics();g.setColor(new Color(0x17191f));g.fillRect(0,0,760,560);g.setColor(new Color(0xf4f2e9));g.fillRoundRect(18,100,724,442,18,18);g.setColor(new Color(0xdadfe3));for(int x=32;x<740;x+=23)g.drawLine(x,100,x,542);for(int y=100;y<542;y+=23)g.drawLine(18,y,742,y);g.setStroke(new BasicStroke(8,BasicStroke.CAP_ROUND,BasicStroke.JOIN_ROUND));g.setColor(new Color(0x8b84cb));Path2D path=new Path2D.Float();path.moveTo(65,347);path.curveTo(240,195,210,470,350,318);g.draw(path);g.setColor(new Color(0x22252d));g.fillRoundRect(30,32,700,64,34,34);for(int i=0;i<10;i++){int x=55+i*65;if(i==6){g.setColor(new Color(0x3d3c53));g.fillRoundRect(x-9,36,43,56,16,16);}g.setColor(new Color(i==6?0xb5b3ff:0x8f95a2));g.fillRoundRect(x+5,48,9,38,3,3);Polygon tip=new Polygon(new int[]{x+5,x+14,x+10},new int[]{48,48,40},3);g.fillPolygon(tip);}g.dispose();return b;}
    static BufferedImage frame(BufferedImage bg,float t){return frame(bg,t,false);}
    static BufferedImage frame(BufferedImage bg,float t,boolean closing){BufferedImage result=new BufferedImage(760,560,BufferedImage.TYPE_INT_RGB);Graphics2D g=result.createGraphics();g.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);g.drawImage(bg,0,0,null);float k=closing?1-PopoverMotion.closing(t):PopoverMotion.expansion(t),shellAlpha=closing?1-PopoverMotion.closing(t):PopoverMotion.opacity(t),textAlpha=closing?1-Math.min(1,t*2.7f):PopoverMotion.content(t),sx=PopoverMotion.lerp(.14f,1,k),sy=PopoverMotion.lerp(43f/292,1,k);float x=306+129.86f*(1-k),y=110-75.5f*(1-k),w=302,h=292;g.translate(x,y);g.scale(sx,sy);float radius=PopoverMotion.lerp(146,26,closing?k:PopoverMotion.corner(t));Shape shell=new RoundRectangle2D.Float(0,0,w,h,radius*2,radius*2);g.setComposite(AlphaComposite.SrcOver.derive(shellAlpha));g.setColor(new Color(0,0,0,30));g.fill(new RoundRectangle2D.Float(0,10,w,h,radius*2,radius*2));g.setColor(new Color(0x45474c));g.fill(shell);g.setPaint(new GradientPaint(0,0,new Color(255,255,255,20),0,h,new Color(255,255,255,0)));g.fill(shell);g.setColor(new Color(255,255,255,45));g.setStroke(new BasicStroke(1));g.draw(shell);g.setClip(shell);g.setComposite(AlphaComposite.SrcOver.derive(textAlpha*shellAlpha));g.setColor(new Color(0xf4f2ed));g.setFont(new Font("SansSerif",Font.BOLD,18));g.drawString("Кисть",16,33);g.setColor(new Color(0xbbbcc6));g.setFont(new Font("SansSerif",Font.PLAIN,11));g.drawString("Нажим · Наклон · Вращение",16,57);g.setColor(new Color(0x252830));g.fillRoundRect(14,72,274,66,16,16);g.setColor(new Color(0xb5b3ff));g.setStroke(new BasicStroke(7,BasicStroke.CAP_ROUND,BasicStroke.JOIN_ROUND));Path2D line=new Path2D.Float();line.moveTo(30,104);line.curveTo(110,65,170,147,266,94);g.draw(line);g.setColor(new Color(0xf4f2ed));g.setFont(new Font("SansSerif",Font.BOLD,12));g.drawString("Толщина",16,165);g.setColor(new Color(0xb5b3ff));g.drawString("12.0 pt",238,165);g.setStroke(new BasicStroke(4,BasicStroke.CAP_ROUND,BasicStroke.JOIN_ROUND));g.setColor(new Color(0x666a75));g.drawLine(27,187,274,187);g.setColor(new Color(0xb5b3ff));g.drawLine(27,187,111,187);g.setColor(Color.WHITE);g.fillOval(104,180,14,14);for(int i=0;i<5;i++){g.setColor(new Color(0x555860));g.fillRoundRect(17+55*i,209,48,27,9,9);g.setColor(new Color(0xf4f2ed));g.drawString(new String[]{"1","3","6","12","24"}[i],35+55*i,227);}int[] colors={0x343b51,0x8b84cb,0x78a997,0xd18a9e,0xd9b760,0x719fc3};for(int i=0;i<6;i++){g.setColor(new Color(colors[i]));g.fillOval(19+i*43,251,24,24);}g.dispose();return result;}
    static void preview(File directory)throws Exception{directory.mkdirs();BufferedImage bg=backdrop();for(int i=0;i<120;i++){float time=i/60f;boolean closing=time>=1.35f;float t=closing?Math.min(1,(time-1.35f)/.18f):Math.max(0,Math.min(1,(time-.25f)/.46f));ImageIO.write(frame(bg,t,closing),"png",new File(directory,String.format("%03d.png",i)));}BufferedImage contact=new BufferedImage(1520,1120,BufferedImage.TYPE_INT_RGB);Graphics2D g=contact.createGraphics();float[] phases={.04f,.13f,.26f,1};for(int i=0;i<phases.length;i++)g.drawImage(frame(bg,phases[i]),i%2*760,i/2*560,null);g.dispose();ImageIO.write(contact,"png",new File(directory.getParentFile(),"Folio-popover-frames.png"));}
    public static void main(String[] args)throws Exception{curve();clock();preview(new File(args[0]));System.out.println("PASS: "+assertions+" motion and frame-clock assertions");}
}
